        [TestCase("class Animal: pass\nclass Dog(Animal): pass\nclass Cat(Animal): pass\nzoo = [Dog(), Cat(), Dog(), 5]\nprint(sum(1 for z in zoo if isinstance(z, Dog)), sum(1 for z in zoo if isinstance(z, Animal)))", "2 3", TestName = "isinstance_of_subclass_instances_in_list")]
        [TestCase("class Shape:\n    def area(self):\n        return 0\nclass Sq(Shape):\n    def __init__(self, s):\n        self.s = s\n    def area(self):\n        return self.s * self.s\nclass Rect(Shape):\n    def __init__(self, w, h):\n        self.w = w\n        self.h = h\n    def area(self):\n        return self.w * self.h\nshapes = [Sq(2), Rect(2, 3), Shape()]\nprint([s.area() for s in shapes], sum(s.area() for s in shapes))", "[4, 6, 0] 10", TestName = "method_resolution_with_isinstance_dispatch")]
        [TestCase("class Stack:\n    def __init__(self):\n        self.items = []\n    def push(self, x):\n        self.items.append(x)\n    def pop(self):\n        if not self.items:\n            raise IndexError('empty')\n        return self.items.pop()\n    def __len__(self):\n        return len(self.items)\ns = Stack()\ns.push(1)\ns.push(2)\nprint(s.pop(), s.pop())\ntry:\n    s.pop()\nexcept IndexError as e:\n    print('IndexError', e)", "2 1\nIndexError empty", TestName = "stack_class_example")]
        [TestCase("class Light:\n    ORDER = ['green', 'yellow', 'red']\n    def __init__(self):\n        self.i = 0\n    def state(self):\n        return Light.ORDER[self.i]\n    def next(self):\n        self.i = (self.i + 1) % len(Light.ORDER)\n        return self.state()\nl = Light()\nprint([l.next() for _ in range(4)])", "['yellow', 'red', 'green', 'yellow']", TestName = "state_machine_example")]
        [TestCase("class Account:\n    rate = 0.5\n    def __init__(self, owner, balance=0):\n        self.owner = owner\n        self.balance = balance\n    def deposit(self, n):\n        if n <= 0:\n            raise ValueError('bad amount')\n        self.balance += n\n        return self.balance\nclass Savings(Account):\n    def add_interest(self):\n        self.balance += self.balance * Account.rate\na = Savings('ann', 100)\na.deposit(50)\na.add_interest()\nprint(a.owner, a.balance)\ntry:\n    a.deposit(-1)\nexcept ValueError as e:\n    print(e)", "ann 225.0\nbad amount", TestName = "bank_account_example")]
        public void MatchesCpython(string source, string expected) => Assert.That(Out(source), Is.EqualTo(expected));
    }
